<?php require 'config.php';$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT e.*,o.nama_organisasi,o.deskripsi org_desc FROM events e JOIN organizations o ON o.user_id=e.organisasi_id WHERE e.kegiatan_id=?");$s->execute([$id]);$ev=$s->fetch();if(!$ev){http_response_code(404);exit('Kegiatan tidak ditemukan');}
$registered=false;if(user()&&user()['role']==='volunteer'){$s=db()->prepare('SELECT status FROM registrations WHERE volunteer_id=? AND kegiatan_id=?');$s->execute([user()['user_id'],$id]);$reg=$s->fetch();$registered=(bool)$reg;}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();require_role('volunteer');if($ev['status']!=='Dipublikasikan'||strtotime($ev['deadline_pendaftaran'])<time()){flash('error','Pendaftaran kegiatan sudah ditutup.');redirect("event.php?id=$id");}
$s=db()->prepare("SELECT COUNT(*) FROM registrations WHERE kegiatan_id=? AND status IN ('Menunggu Verifikasi','Diterima')");$s->execute([$id]);$count=(int)$s->fetchColumn();
if($count >= (int)$ev['kuota']){flash('error','Kuota kegiatan telah penuh.');redirect("event.php?id=$id");}
try{db()->prepare("INSERT INTO registrations(volunteer_id,kegiatan_id) VALUES(?,?)")->execute([user()['user_id'],$id]);flash('success','Pendaftaran tersimpan dengan status Menunggu Verifikasi.');}catch(Throwable $e){flash('error','Kamu sudah pernah mendaftar pada kegiatan ini.');}redirect("event.php?id=$id");}
layout_start($ev['nama_kegiatan']);?><a class="back" href="index.php">← Kembali ke kegiatan</a><div class="detail-grid"><article class="detail-main"><span class="category"><?=e($ev['kategori'])?></span><h1><?=e($ev['nama_kegiatan'])?></h1><p class="muted">Diselenggarakan oleh <b><?=e($ev['nama_organisasi'])?></b></p><div class="detail-box"><h3>Tentang kegiatan</h3><p><?=nl2br(e($ev['deskripsi']))?></p><h3>Persyaratan</h3><p><?=nl2br(e($ev['persyaratan']?:'Tidak ada persyaratan khusus.'))?></p></div></article><aside class="detail-side"><h3>Informasi kegiatan</h3><p>📅 <b><?=date('d F Y, H:i',strtotime($ev['tanggal']))?></b></p><p>⌖ <?=e($ev['lokasi'])?></p><p>◷ <?=e($ev['durasi_jam'])?> jam</p><p>👥 <?=e($ev['kuota'])?> peserta</p><p>Deadline: <?=date('d M Y H:i',strtotime($ev['deadline_pendaftaran']))?></p><?php if(user()&&user()['role']==='volunteer'):?><?php if($registered):?><p><?=badge($reg['status'])?></p><?php elseif($ev['status']==='Dipublikasikan'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="btn btn-primary full">Daftar kegiatan</button></form><?php endif;?><?php elseif(!user()):?><a class="btn btn-primary full" href="login.php">Masuk untuk mendaftar</a><?php endif;?></aside></div><?php layout_end(); ?>